inline const entry_t* find( unsigned id )
{
  std::size_t n = 0;
  const entry_t* t = table( n );
  for ( std::size_t i = 0; i < n; i++ )
    if ( t[ i ].id == id )
      return &t[ i ];
  return nullptr;
}

// One conduit socket: the id the game reports and the rank it reports, which is
// one-based. Anything not socketed simply is not in the map.
struct set_t
{
  std::string option;
  std::unordered_map<unsigned, unsigned> ranks;

  // "20:11/21:11" - the shape the BracketSimDump addon emits.
  void parse()
  {
    ranks.clear();
    for ( const auto& tok : util::string_split<util::string_view>( option, "/" ) )
    {
      auto parts = util::string_split<util::string_view>( tok, ":" );
      if ( parts.size() != 2 )
        continue;
      unsigned id = util::to_unsigned( parts[ 0 ] );
      unsigned rk = util::to_unsigned( parts[ 1 ] );
      if ( id > 0 && rk > 0 )
        ranks[ id ] = rk;
    }
  }

  bool has( unsigned id ) const
  { return ranks.find( id ) != ranks.end(); }

  // The raw DBC value at the socketed rank, or 0 when the conduit is not in.
  double value( unsigned id ) const
  {
    auto it = ranks.find( id );
    if ( it == ranks.end() )
      return 0.0;
    const entry_t* e = find( id );
    if ( !e )
      return 0.0;
    unsigned idx = it->second - 1u;          // reported rank is one-based
    if ( idx >= MAX_RANK )
      idx = MAX_RANK - 1u;
    return e->rank[ idx ];
  }

  double percent( unsigned id ) const
  { return value( id ) / 100.0; }
};

